using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderFluidOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private readonly FluidBridgeOperations _fluid=new();private readonly FluidSolverOperations _solver=new();private readonly PhysicsCollisionWorldOperations _collision=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static Settings Map(GodotObject owner,string key)=>owner.Get(key).AsGodotDictionary();private static Vector3I Cell(Vector3 point,double h){var c=(point/(float)h).Floor();return new Vector3I((int)c.X,(int)c.Y,(int)c.Z);}
    internal sealed class Fluid{internal Settings Row,State,Values,Grid;internal Vector3[] Points,Velocities;internal float[] Masses;internal double H,Speed;internal bool Moving;internal Fluid(Settings row){Row=row;State=row["state"].AsGodotDictionary();Values=row["values"].AsGodotDictionary();Grid=row["grid"].AsGodotDictionary();H=row["h"].AsDouble();Speed=row["speed"].AsDouble();Moving=row["moving"].AsBool();Points=State["points"].AsVector3Array();Velocities=State["velocities"].AsVector3Array();Masses=State["fluid_masses"].AsFloat32Array();}internal void Commit(){State["points"]=Points;State["velocities"]=Velocities;}}
    public GArray fluids(RefCounted controller,Settings batch,double time){var result=new GArray();var prototypes=Map(controller,"prototypes");var config=batch["config"].AsGodotDictionary();foreach(var id in prototypes.Keys){var state=Map(controller,"states")[id].AsGodotDictionary();var points=state["points"].AsVector3Array();if(state["type"].AsInt32()!=6||!state["active"].AsBool()||!state["initialized"].AsBool()||points.Length==0)continue;var actor=prototypes[id].AsGodotDictionary()["actor"].As<Resource>();var settings=_settings.sample(actor,controller.Call("_local",actor,time).AsDouble());if(!config["collision"].AsBool()||!settings["collision"].AsBool()||(config["mask"].AsInt32()&settings["layer"].AsInt32())==0||(settings["mask"].AsInt32()&config["layer"].AsInt32())==0)continue;var values=_fluid.values(controller,id.AsString(),time);double h=values["spacing"].AsDouble()*2.05;var grid=new Settings();for(int i=0;i<points.Length;i++){var cell=Cell(points[i],h);if(!grid.ContainsKey(cell))grid[cell]=new GArray();grid[cell].AsGodotArray().Add(i);}result.Add(new Settings{["id"]=id,["state"]=state,["values"]=values,["grid"]=grid,["h"]=h,["moving"]=settings["mode"].AsInt32() is 1 or 2,["speed"]=prototypes[id].AsGodotDictionary()["clip"].As<Resource>().Get("playback_speed")});}return result;}
    internal static int[] Near(Fluid fluid,Vector3 point){var cell=Cell(point,fluid.H);var result=new List<int>();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(fluid.Grid.TryGetValue(cell+new Vector3I(x,y,z),out var items))foreach(var value in items.AsGodotArray()){int i=value.AsInt32();if(point.DistanceSquaredTo(fluid.Points[i])<fluid.H*fluid.H)result.Add(i);}return result.ToArray();}
    public int[] near(Settings fluid,Vector3 point){double h=fluid["h"].AsDouble();var cell=Cell(point,h);var grid=fluid["grid"].AsGodotDictionary();var points=fluid["state"].AsGodotDictionary()["points"].AsVector3Array();var result=new List<int>();for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(grid.TryGetValue(cell+new Vector3I(x,y,z),out var items))foreach(var value in items.AsGodotArray()){int i=value.AsInt32();if(point.DistanceSquaredTo(points[i])<h*h)result.Add(i);}return result.ToArray();}
    public void forces(RefCounted controller,GArray batches,double time)
    {
        foreach(var value in batches){var batch=value.AsGodotDictionary();var settings=batch["settings"].AsGodotDictionary();double strength=settings["fluid_strength"].AsDouble();if(!batch["moving"].AsBool()||strength<=0)continue;var state=batch["state"].AsGodotDictionary();double dt=batch["h"].AsDouble(),grainSpeed=Map(controller,"prototypes")[batch["id"]].AsGodotDictionary()["clip"].As<Resource>().Get("playback_speed").AsDouble();var points=state["points"].AsVector3Array();var velocities=state["velocities"].AsVector3Array();var phase=Get(state,"powder_phase",Array.Empty<byte>()).AsByteArray();var radii=state["powder_radii"].AsFloat32Array();var sleep=state["powder_sleep"].AsFloat32Array();foreach(var row in fluids(controller,batch,time)){var fluid=new Fluid(row.AsGodotDictionary());for(int i=0;i<points.Length;i++){if(phase.Length>0&&phase[i]==1)continue;var neighbors=Near(fluid,points[i]);var weights=new float[neighbors.Length];double total=0;var velocity=Vector3.Zero;for(int k=0;k<neighbors.Length;k++){int j=neighbors[k];double weight=_solver.kernel(points[i].DistanceSquaredTo(fluid.Points[j]),fluid.H)*Math.Pow(fluid.Values["spacing"].AsDouble(),3);weights[k]=(float)weight;total+=weight;velocity+=fluid.Velocities[j]*(float)(weight*fluid.Speed/Math.Max(.001,grainSpeed));}if(total<=.000001)continue;velocity/=(float)total;double radius=radii[i],mass=settings["density"].AsDouble()*4/3*Math.PI*Math.Pow(radius,3),occupancy=Math.Clamp(total,0,1);var relative=velocity-velocities[i];double drag=.5*fluid.Values["fluid_density"].AsDouble()*.47*Math.PI*radius*radius/mass*relative.Length()*occupancy*strength;var change=relative*(float)(1-Math.Exp(-drag*dt));change-=batch["gravity"].AsVector3()*(float)(settings["gravity_scale"].AsDouble()*fluid.Values["fluid_density"].AsDouble()/settings["density"].AsDouble()*occupancy*strength*dt);velocities[i]+=change;sleep[i]=0;if(fluid.Moving)for(int k=0;k<neighbors.Length;k++){int j=neighbors[k];fluid.Velocities[j]-=change*(float)(mass/Math.Max(.000001,fluid.Masses[j])*weights[k]/total*grainSpeed/Math.Max(.001,fluid.Speed));}}fluid.Commit();}state["velocities"]=velocities;state["powder_sleep"]=sleep;}
    }
    public void contacts(RefCounted controller,GArray batches,double time)
    {
        foreach(var value in batches){var batch=value.AsGodotDictionary();var settings=batch["settings"].AsGodotDictionary();if(!batch["moving"].AsBool()||settings["fluid_strength"].AsDouble()<=0)continue;var state=batch["state"].AsGodotDictionary();double h=Math.Max(.000001,batch["h"].AsDouble()),grainSpeed=Map(controller,"prototypes")[batch["id"]].AsGodotDictionary()["clip"].As<Resource>().Get("playback_speed").AsDouble();var points=state["points"].AsVector3Array();var velocities=state["velocities"].AsVector3Array();var phase=Get(state,"powder_phase",Array.Empty<byte>()).AsByteArray();var radii=state["powder_radii"].AsFloat32Array();var masses=state["powder_masses"].AsFloat32Array();foreach(var row in fluids(controller,batch,time)){var fluid=new Fluid(row.AsGodotDictionary());var oldGrains=(Vector3[])points.Clone();var oldFluid=(Vector3[])fluid.Points.Clone();var touched=new HashSet<int>();double fluidRadius=fluid.Values["spacing"].AsDouble()*.32;for(int i=0;i<points.Length;i++)foreach(int j in Near(fluid,points[i])){var delta=points[i]-fluid.Points[j];double distance=delta.Length(),rest=radii[i]+fluidRadius;if(distance>=rest)continue;var normal=delta/(float)Math.Max(.000001,distance);if(distance<.000001)normal=Vector3.Up;bool attached=phase.Length>0&&phase[i]==1;double a=attached?0:1/Math.Max(1e-9,masses[i]),b=fluid.Moving?1/Math.Max(1e-9,fluid.Masses[j]):0;if(a+b<=0)continue;var correction=normal*(float)(Math.Min((rest-distance)*Math.Clamp(settings["fluid_strength"].AsDouble(),0,1),radii[i]*.2)/(a+b));var grainDelta=correction*(float)a;var fluidDelta=-correction*(float)b;points[i]+=grainDelta;velocities[i]+=grainDelta/(float)h;if(fluid.Moving){fluid.Points[j]+=fluidDelta;fluid.Velocities[j]+=fluidDelta*(float)(grainSpeed/(h*Math.Max(.001,fluid.Speed)));touched.Add(j);}}
            var world=controller.Get("world").As<RefCounted>();if(world.Get("space").AsRid().IsValid){var config=batch["config"].AsGodotDictionary();for(int i=0;i<points.Length;i++){if(points[i]==oldGrains[i])continue;var safe=_collision.point_motion(world,batch["id"].AsString(),oldGrains[i],points[i],radii[i],config["layer"].AsInt32(),config["mask"].AsInt32(),new GArray());var position=safe["position"].AsVector3();velocities[i]+=(position-points[i])/(float)h;points[i]=position;}foreach(int j in touched){var actor=Map(controller,"prototypes")[fluid.Row["id"]].AsGodotDictionary()["actor"].As<Resource>();var fluidConfig=_settings.sample(actor,controller.Call("_local",actor,time).AsDouble());var safe=_collision.point_motion(world,fluid.Row["id"].AsString(),oldFluid[j],fluid.Points[j],fluidRadius,fluidConfig["layer"].AsInt32(),fluidConfig["mask"].AsInt32(),new GArray());var position=safe["position"].AsVector3();fluid.Velocities[j]+=(position-fluid.Points[j])*(float)(grainSpeed/(h*Math.Max(.001,fluid.Speed)));fluid.Points[j]=position;}}for(int i=0;i<velocities.Length;i++)velocities[i]=velocities[i].LimitLength(settings["max_speed"].AsSingle());foreach(int j in touched)fluid.Velocities[j]=fluid.Velocities[j].LimitLength(fluid.Values["fluid_max_speed"].AsSingle());fluid.Commit();}state["points"]=points;state["velocities"]=velocities;}
    }
}
